"""VMT 扫描 + SP PNG 匹配（零 GUI 依赖）。"""

from pathlib import Path
from .parse_vmt import parse_vmt, image_size
from .constants import PARAM_PREFERRED, VMT_STRIP_SUFFIXES


def sp_prefixes(vmt_stem, basetexture_rel=None, bumpmap_rel=None):
    """从 VMT 文件名和参数值提取可能的前缀（用于匹配 SP PNG 命名变体）。"""
    prefixes = {vmt_stem}
    for rel in (basetexture_rel, bumpmap_rel):
        if rel:
            name = Path(rel.replace("\\", "/")).stem
            prefixes.add(name)
            while True:
                for sfx in VMT_STRIP_SUFFIXES:
                    if name.endswith(sfx):
                        name = name[:-len(sfx)]
                        prefixes.add(name)
                        break
                else:
                    break
    return prefixes


def fuzzy_match(vmt_texture_path, png_by_name):
    """尝试模糊匹配 VMT 纹理路径与已知 PNG 文件名。"""
    vmt_base = Path(vmt_texture_path).stem.lower()
    for name_l, png_path in png_by_name.items():
        stem_l = name_l.rsplit(".", 1)[0]
        if stem_l == vmt_base:
            return png_path
        if stem_l.startswith(vmt_base) or vmt_base.startswith(stem_l):
            return png_path
    return None


def scan_vmts(vmt_dir, png_dir, default_w=1024, default_h=1024):
    """扫描 VMT 目录，匹配 SP PNG/TGA，返回工作项列表。

    返回: list[dict]，每个 dict 包含:
        vmt_path: str, params: dict, base: dict, normal: dict
    """
    vmt_dir = Path(vmt_dir)
    png_dir = Path(png_dir) if png_dir else None

    if not vmt_dir.is_dir():
        raise FileNotFoundError(f"VMT 目录不存在: {vmt_dir}")

    vmts = sorted(vmt_dir.glob("*.vmt"))
    if not vmts:
        raise ValueError("VMT 目录下没有 .vmt 文件")

    png_by_name = {}
    if png_dir and png_dir.is_dir():
        for f in png_dir.iterdir():
            sfx = f.suffix.lower()
            if sfx in (".png", ".tga"):
                png_by_name[f.name.lower()] = f

    png_stems = [(name_l.rsplit(".", 1)[0].lower(), path) for name_l, path in png_by_name.items()]

    results = []
    for vmt in vmts:
        try:
            params = parse_vmt(vmt)
        except Exception:
            continue

        sp_pfx = sp_prefixes(
            vmt.stem,
            params.get("$basetexture"),
            params.get("$bumpmap"),
        )

        candidates = {}
        pfx_lower_set = {p.lower() for p in sp_pfx}
        for stem_l, png_path in png_stems:
            for pfx in pfx_lower_set:
                if stem_l.startswith(pfx + "_"):
                    suffix = stem_l[len(pfx):]
                    if suffix not in candidates:
                        candidates[suffix] = png_path

        assigned_suffixes = set()
        slots = {}

        for slot, param, preferred in PARAM_PREFERRED:
            rel = params.get(param.lower())
            png = None
            matched_suffix = None

            for sfx in preferred:
                key = sfx.lower()
                if key in candidates and key not in assigned_suffixes:
                    png = candidates[key]
                    assigned_suffixes.add(key)
                    matched_suffix = sfx
                    break

            if png is None:
                for suffix, png_path in candidates.items():
                    if suffix not in assigned_suffixes:
                        png = png_path
                        assigned_suffixes.add(suffix)
                        matched_suffix = suffix.lstrip("_")
                        break

            if png is None and rel:
                png = fuzzy_match(rel, png_by_name)

            exists = png is not None and png.is_file()
            size = image_size(png) if exists else None
            enabled = bool(rel) and exists
            if size:
                tw = max(128, min(4096, size[0]))
                th = max(128, min(4096, size[1]))
            else:
                tw, th = default_w, default_h

            fallback_png = str((png_dir / f"{vmt.stem}.png") if png_dir else vmt.with_suffix(".png"))
            slots[slot] = {
                "enabled": enabled,
                "checked": enabled,
                "png": str(png) if exists else fallback_png,
                "rel": rel or "",
                "param": param,
                "size": size,
                "target_w": tw,
                "target_h": th,
                "suffix": matched_suffix,
            }

        results.append({
            "vmt_path": str(vmt),
            "vmt_name": vmt.name,
            "params": params,
            "base": slots["base"],
            "normal": slots["normal"],
        })

    return results
